export function getASMLAProfile(acNo: number): MLAProfile | undefined {
  return AS_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getASMLAsByParty(party: string): MLAProfile[] {
  return AS_MLA_PROFILES.filter(p => p.party === party);
}

export function getASFemaleMLAs(): MLAProfile[] {
  return AS_MLA_PROFILES.filter(p => p.gender === 'F');
}
